{"cmd":"cd data/reports && python3 << 'PYEOF'
import re

tickers = ['COP', 'ECL', 'GE', 'GIS', 'IDXX', 'PWR', 'RCL', 'ROP', 'SJM', 'STZ']
for ticker in tickers:
    fname = f"{ticker}_2024_10K.md"
    with open(fname, 'r') as f:
        content = f.read()

    # Find Item 7A
    m = re.search(r'#{1,3}\s*ITEM\s*7A[\.\s].*?(?=#{1,3}\s*ITEM\s*8|\Z)', content, re.IGNORECASE | re.DOTALL)
    if m:
        section = m.group(0)
        # Find interest rate related content
        interest_section = re.search(r'Interest Rate Risk.*?(?=\n#{1,3}|\n## [A-Z])', section, re.IGNORECASE | re.DOTALL)
        if interest_section:
            print(f"=== {ticker} Interest Rate Risk ===")
            print(interest_section.group(0)[:2000])
        else:
            # Search for "interest rate" in section
            lines = section.split('\n')
            for i, line in enumerate(lines):
                if 'interest' in line.lower() and ('rate' in line.lower() or 'variable' in line.lower() or 'floating' in line.lower()):
                    start = max(0, i-2)
                    end = min(len(lines), i+30)
                    print(f"=== {ticker} (around line {i}) ===")
                    print('\n'.join(lines[start:end]))
                    break
            else:
                print(f"=== {ticker} === No interest rate content found in Item 7A")
        print()
    else:
        print(f"=== {ticker} === Item 7A NOT FOUND")
        print()
PYEOF"}

